Ext.define('BNK.view.Budget.exp.ExpNteDoc02MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.ExpNteDoc02MViewController',

    alternateClassName: [
        'ExpNteDoc02MViewController'
    ],

    config: {
        viewId: 'ExpNteDoc02M'
    },

    recoveryFormRender: function(records) {
        for(var i in records){
            records[i].apvlAmtDom = String(records[i].apvlAmtDom).replace(/,/gi, '');
            records[i].apvlAmtDom = String(records[i].apvlAmtDom).replace(/ 원/gi, '');

            records[i].apvlDt    = String(records[i].apvlDt).replace(/-/gi, '').substring(0, 8);
            records[i].apvlHr    = String(records[i].apvlHr).replace(/:/gi, '');

            if(records[i].canYn != 'Y' && records[i].canYn != 'N'){
                records[i].canYn = this.getValue('NTE008', records[i].canYn);
            }

            records[i].cdno      = String(records[i].cdno).replace(/-/gi, '');
            records[i].mcBzno    = String(records[i].mcBzno).replace(/-/gi, '');

            if(records[i].stxat){
                records[i].stxat = String(records[i].stxat).replace(/,/gi, '');
                records[i].stxat = String(records[i].stxat).replace(/ 원/gi, '');
            }
            if(records[i].trnsAmtWc){
                records[i].trnsAmtWc = String(records[i].trnsAmtWc).replace(/,/gi, '');
                records[i].trnsAmtWc = String(records[i].trnsAmtWc).replace(/ 원/gi, '');
            }

        }

        return records;

    },

    /* text -> value */
    getValue: function(code, text) {

            var codeStore = Ext.StoreMgr.get('CodeStore'), items = codeStore.getData().items;
            var cbData = [];
            var isFound = false;
            var result = '';

            for (var i = 0, l = items.length; i < l; i++) {
              if (code === items[i].data.code) {
                var children = items[i].data.children;
                for (var j = 0, l2 = children.length; j < l2; j++) {
                  var item = children[j];
                  if (text == item.text) {
                    result = item.value;
                    isFound = true;
                    break;
                  }
                }
                if (isFound) {
                  break;
                }
              }
            }
            return result;

    },

    /* 영수증 버튼 탭 이벤트 */
    onOpenReceipt: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            popupData = vm.get('popupData'),
            win = Ext.create('ExpNteDoc52M', {
                popupData : popupData
            });

        me.mon(win, 'complete', function() {
            var me = this;
        }, me);

        win.show();

    },

    /* 결재정보 버튼 탭 이벤트 */
    onAplyInfo: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            record = vm.get('popupData'),
            aprHistId = record[0].comAprHistId,
            edocCd = record[0].stlmDvcd === '01' ? 'ExpNteAply71' : 'ExpNteRcpt71';

        // 선택한 결재선 레코드. 동시성제어에 사용
        vm.set('record', record);

        // 결재이력데이터조회
        Ext.Ajax.request({
            headers : {
                serviceId : 'COMAPR0001R04M',
                viewId : 'ExpNteApr02M'
            },
            scope : me,
            jsonData : {
                aprHistId : aprHistId // 결재이력아이디
            },
            success : function(response) {
                var me = this,
                    refs = me.getReferences(),
                    vm = me.getViewModel(),
                    command = vm.get('command'),
                    responseJson = Ext.JSON.decode(Ext.JSON.decode(response.responseText).result);

                if (!responseJson) {
                    Ext.Msg.alert('안내', '결재이력데이터가 존재하지 않습니다.');
                    return;
                }

                vm.set('responseJson', responseJson);

                var aprViewId = responseJson.edocCd + 'M',	// 모바일일경우, 화면이름에 M을 붙여처리함
                classname = me.GET_CLASS_NAME(aprViewId);
                if (!classname) {
                    Ext.Msg.alert('안내', Ext.String.format('{0}에 해당하는 파일이 존재하지 않습니다.', aprViewId));
                    return;
                }

                // 부서완료함(97)과 담당자완료함(98)은 완료함(94)과 동일한 기능을 하도록 설정
                var commandArr = ['97', '98'];
                if(commandArr.includes(command)){
                    command = '94';
                }

                // 과거데이터와 호환성을 위한처리 추가
                var aprHistId = responseJson.aprHistId,
                    docData = responseJson.docData;
                if (!docData) {
                    docData = {};
                    if (responseJson.fieldValues)  docData.fieldValues  = responseJson.fieldValues;
                    if (responseJson.afterchange)  docData.afterchange  = responseJson.afterchange;
                    if (responseJson.beforechange) docData.beforechange = responseJson.beforechange;
                }

                var win = Ext.create(aprViewId, {
                    command : command,
                    aprHistId : aprHistId,
                    docData : docData,
                    record : vm.get('record'),
                    onlyGrid : true
                });

                me.mon(win, 'complete', function(popup) {
                    popup.close(); //팝업창닫기
                    me.onSelect();
                }, me);

                win.show();
            }
        });




        // var me = this,
        //     vm = me.getViewModel(),
        //     popupData = vm.get('popupData'),
        //     win = Ext.create('ExpNteDoc51M', {
        //         popupData : popupData
        //     });

        // me.mon(win, 'complete', function() {
        //     var me = this;
        // }, me);

        // win.show();

    },

    Initialize: function(component, eOpts) {
        return false; // 사용안하는 화면 (71로 대체함)

        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var items = component.datas;
        var apvlAmtDomTotal = 0;

        items = this.recoveryFormRender(items);

        for(var i in items){
            items[i].isAply = true; // 결재 화면으로 사용하는 Items에서는 readOnly 처리하기 위해 사용하는 플래그
            items[i].rgdt = items[i].aplDt; // 신청일자
            items[i].hrHromJasPrjText = items[i].prjNm; // 사용부문 text
        }

        /* 단건만 오기 때문에 0으로 고정 */
        var aplDt = items[0].aplDt;
        aplDt = aplDt.substr(0, 4) + '-' + aplDt.substr(4, 2) + '-' + aplDt.substr(6, 2);

        var stlmDvcdCode = items[0].stlmDvcd,
            stlmDvcd = (stlmDvcdCode === '01') ? '법인카드' : '기타영수증';
        refs.item_container.getViewModel().set('stlmDvcd', stlmDvcd);

        if(stlmDvcdCode === '01'){ // 법인카드인 경우 영수증 버튼 hidden
            refs.btnReceipt.setHidden(true);
        } else {// 기타영수증인 경우
            refs.item_container.getViewModel().set('etcRcpt', true);
        }

        refs.item_container.getViewModel().set('record.rgdt', aplDt); // 상신일 전달을 위한 vm // 현황 화면 외 다른화면과의 호환성을 가지기 위함
        refs.item_container.getViewModel().set('records', items);
        refs.item_container.getViewModel().set('doc', true);

        for(var i in items){
            apvlAmtDomTotal += Number(items[i].apvlAmtDom);
        }
        var str = String(apvlAmtDomTotal);
        apvlAmtDomTotal = str.replace(/(\d)(?=(?:\d{3})+(?!\d))/g, '$1,');

        vm.set('cardCnt', items.length);
        vm.set('apvlAmtDomTotal', apvlAmtDomTotal);
        vm.set('popupData', items);

        refs.item_container.controller.addForm();

        var edocCd = (stlmDvcdCode === '01') ? 'ExpNteAply71' : 'ExpNteRcpt71';
        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command   : '01',
            viewModel : vm,
            edocCd    : edocCd,
            scope     : me
        });


    }

});